程序设计实习报告 桂林理工大学 GUILIN UNIVERSITY OF TECHNOLOGY
程序设计实践课程 实习报告
学 院： 计算机科学与工程学院 # 班 级： ## 组 长： 组 员： 组 员： 组 员： 指导教师： 评 分/价：
1.基础实践部分
1.1. 编写程序，求n！ 1.1.1题目内容 编写程序，求n！(n的值要能大于13)，其结果用一个不超过64位的十进制数输出。
1.1.2题目要求 【输入格式】 输入一个非负整数，其值介于2到49之间的数。 【输出格式】 对每一个输入的整数，在一行中输出相应的阶乘值，输出结果的高位用0填充。 【输入样例】 在这里给出一组输入。例如： 7 结尾无空行 【输出样例】 5040
1.1.3设计思想 deepseek_mermaid_20260108_2d339a.png
1.1.4算法分析 时间复杂度：O(n² log n) 空间复杂度：O(n log n) 1.1.5核心代码 // 编写程序,求n! #include #include #include #include using namespace std;
string calculate(int n) { if (n == 0 || n == 1) { return &ldquo;1&rdquo;; }
vector&lt;int&gt; result; result.push_back(1); for (int i = 2; i &lt;= n; i++) { int carry = 0; // 将每个结果乘以i for (int j = 0; j &lt; result.size(); j++) { int product = result[j] * i + carry; result[j] = product % 10; carry = product /= 10; } // 处理剩余进位 while (carry &gt; 0) { result.push_back(carry % 10); carry /= 10; } } // 高位填充0 for (int i = 0 ; i &lt; 64 - result.size(); i++) { result.push_back(0); } // 转换为0 string res; reverse(result.begin(),result.end()); for (int i = 0; i &lt; result.size(); i++) { res += to_string(result[i]); } return res; }
int main() { int n; cin &raquo; n;
string result = calculate(n); cout &lt;&lt; result &lt;&lt; endl; }
1.1.6测试数据或截图 image.png
1.1.7心得体会 在本次程序设计实习中，我通过实现大数阶乘计算，深入理解了数组模拟高精度运算的原理和实现细节，锻炼了问题分解和逻辑思维能力。
1.2 找最大数和最小数 1.2.1题目内容 本题目要求读入n个整数，找到最大数和最小数，并输出结果。
1.2.2题目要求 【输入格式】 例如当n=4时，输入给出4个绝对值不超过1000的整数A、B、C、D，以空格分隔。 【输出格式】 最大数和最小数，“max=?,min=?”。 【输入样例】 在这里给出一组输入。例如： 18 98 59 25 【输出样例】 在这里给出相应的输出。例如： max=98, min=18
1.2.3设计思想
deepseek_mermaid_20260108_33f2cf.png
1.2.4算法分析 时间复杂度：O(n) 空间复杂度：O(n)
1.2.5核心代码 // 找最大数和最小数 #include #include #include #include using namespace std;
int main() { int n; cin &raquo; n; vector nums(n); cin &raquo; nums[0]; int max_num = nums[0]; int min_num = nums[0]; for (int i = 1; i &lt; n; i++) { cin &raquo; nums[i]; max_num = max(max_num,nums[i]); min_num = min(min_num,nums[i]); }
cout &lt;&lt; &quot;max_num=&quot; &lt;&lt; max_num &lt;&lt; &quot;min_num=&quot; &lt;&lt; min_num; }
1.2.6测试数据或截图 image.png
1.2.7心得体会 初次编写查找最值程序时，我意识到在循环中同时更新最大最小值能有效减少遍历次数，对时间复杂度有了更直观的理解，也学会了注意数组边界等细节
1.3 统计字母出现频率 1.3.1题目内容 输入一段文字（以回车结束），统计其中每个字母出现的频率。
1.3.2题目要求 【输入格式】 一段文字（以回车结束） 【输出格式】 统计结果（包括次数和百分比，并显示条状图，参见输出样例） 【输入样例】 This is a pen. That is a pencil. 【输出样例】 A: 3 13.0% ************* C: 1 4.3% **** E: 2 8.7% ********* H: 2 8.7% ********* I: 4 17.4% ***************** L: 1 4.3% **** N: 2 8.7% ********* P: 2 8.7% ********* S: 3 13.0% ************* T: 3 13.0% *************
1.3.3设计思想 deepseek_mermaid_20260108_bb824e.png
1.3.4算法分析 时间复杂度：O(n) 空间复杂度：O(1)
1.3.5核心代码 // 统计字母出现频率 #include #include #include #include #include using namespace std;
int main() { string str_input; cin &raquo; str_input; vector cnt(26); for (int i = 0; i &lt; str_input.size(); i++) { cnt[str_input[i] - &lsquo;a&rsquo;] += 1; } int total = 0; for (int i = 0; i &lt; cnt.size(); i++) { total += cnt[i]; } for (int i = 0; i &lt; cnt.size(); i++) { // 输出统计对象 cout &laquo; char(&lsquo;A&rsquo; + i) &laquo; &quot; &ldquo;; // 输出统计个数 cout &laquo; cnt[i] &laquo; &quot; &quot; &laquo; endl;
// 输出百分比 double temp = (cnt[i] * 100) / (double)total; // 限制小数点两位 cout &lt;&lt; fixed &lt;&lt; setprecision(2) &lt;&lt; temp &lt;&lt; &quot;%&quot;; // 输出条状图 int each = (cnt[i] * 100) / total ; if ((cnt[i] * 100) / total &gt; 0) { each += 1; } for (int i = 0; i &lt; each; i++) { cout &lt;&lt; &quot;*&quot;; } cout &lt;&lt; endl; } }
1.3.6测试数据或截图 image.png
1.3.7心得体会 通过这次字母频率统计程序的编写，我学会了如何将抽象的数据统计需求转化为具体代码逻辑，掌握了数组映射和格式化输出的技巧，意识到程序不仅要关注正确性，输出格式的可读性也同样重要。
1.4最小公倍数 1.4.1题目内容 请编写程序，输入两个整数，计算并输出它们的输出最小公倍数。
1.4.2题目要求 【输入格式】 两个整数 【输出格式】 最小公倍数(正整数) 说明：两个整数可以是正数、零和负数。最小公倍数必须是自然数。题目保证两个整数及其最小公倍数的绝对值都小于2(63) 。 【输入样例】 935761 -5128800173759 【输出样例】 4799331179396895599
1.4.3设计思想 deepseek_mermaid_20260108_05f056.png
1.4.4算法分析 时间复杂度：O(log(min(a, b))) 空间复杂度：O(1)
1.4.5核心代码 // 最小公倍数 // 辗转相除法: // lcm: 最小公倍数 gcd: 最大公约数 // LCM(a, b) = |a × b| ÷ GCD(a, b) #include #include #include #include #include using namespace std;
// 求解最大公约数 long long gcd(long long a, long long b) { // 反复用余数替换原数相除，直至整除，最后的除数即为最大公约数。 while(b != 0) { long long temp = b; b = a % b; a = temp; } return a; }
// 求解最小公约数 long long lcm(long long a, long long b) { // 防止溢出: 先除最大公约数再乘 return a / gcd(a, b) * b; }
int main() { long long num1,num2; cin &raquo; num1 &raquo; num2; long long gcd_num = gcd(num1,num2); long long lcm_num = lcm(num1,num2); cout &laquo; lcm_num &laquo; endl; }
1.4.6测试数据或截图 image.png
1.4.7心得体会 通过这个程序，我明白了数学算法在编程中的重要性。辗转相除法求最大公因数的方法简洁高效，而最小公倍数与最大公因数的数学关系让我领略到算法设计的巧妙。同时，先除后乘的顺序处理让我注意到整数溢出的预防，这些都是很实用的编程经验。
1.5学车费用 1.5.1题目内容 小华学开车后，才发现他的教练对不同的学员收取不同的费用。小华想分别对他所了解到的学车同学的各项费用进行累加求出总费用，然后按下面的排序规则排序并输出，以便了解教练的收费情况。排序规则： 先按总费用从多到少排序，若总费用相同则按姓名的ASCII码序从小到大排序，若总费用相同而且姓名也相同则按编号（即输入时的顺序号，从1开始编）从小到大排序。
1.5.2题目要求 【输入格式】 测试数据有多组，处理到文件尾。每组测试数据先输入一个正整数n（n≤20），然后是n行输入，第i行先输入第i个人的姓名（长度不超过10个字符，且只包含大小写英文字母），然后再输入若干个整数（不超过10个），表示第i个人的各项费用，数据之间都以一个空格分隔，第i行输入的编号为i。输入数据和结果均在32位int型范围之内。 【输出格式】 对于每组测试，在按描述中要求的排序规则进行排序后，按顺序逐行输出每个人费用情况，包括：费用排名（从1开始，费用相同则排名也相同）、编号、姓名、总费用。每行输出的数据之间留1个空格。 【输入样例】 3 Tim 2800 900 2000 500 600 Lucy 3800 400 1500 300 Tim 6700 100
【输出样例】 1 1 Tim 6800 1 3 Tim 6800 3 2 Lucy 6000
1.5.3设计思想 deepseek_mermaid_20260108_9eac00.png
1.5.4算法分析 时间复杂度接近O(n × m) 空间复杂度高：O(n × m)
1.5.5核心代码
// 学车费用 // 排序规则： 先按总费用从多到少排序，若总费用相同则按姓名的ASCII码序从小到大排序， // 若总费用相同而且姓名也相同则按编号（即输入时的顺序号，从1开始编）从小到大排序。
/* 知识点补充: stringstream 是C++中一个强大的流类,用于字符串的输入输出操作 #include // 必须包含这个头文件 stringstream：既可读又可写 istringstream：只读（从字符串读取） ostringstream：只写（写入字符串）
stringstream 是一个字符串流，它把字符串当作一个连续的字符序列， 并维护一个内部指针来跟踪当前读取位置。 提取运算符 &gt;&gt;：根据目标类型读取数据 */
#include #include #include #include #include #include using namespace std;
class Student { public: string m_name; vector m_prices; int m_total; int m_id; Student() : m_total(0) , m_id(0) {} };
static bool compare(Student stu1, Student stu2) { // 如果费用相等,按照姓名排序 if (stu1.m_total == stu2.m_total) { // 如果姓名也相同,按照输入顺序排序 if (stu1.m_name == stu2.m_name) { return stu1.m_id &lt; stu2.m_id; } return stu1.m_name &lt; stu2.m_name; } else { // 费用由多到少排序 return stu1.m_total &gt; stu2.m_total; } }
int main() { int n; cin &raquo; n; cin.ignore(); // 忽略第一行后面的换行符
// 读取并且创建学生类 vector&lt;Student&gt; students(n); for (int i = 0; i &lt; n; i++) { string line; getline(cin, line); // 读取整行 stringstream ss(line); // 读取id students[i].m_id = i + 1; // 读取姓名 string name; ss &gt;&gt; name; students[i].m_name = name; // 读取各个费用 // 这里读取到回车就终止 int price; while(ss &gt;&gt; price) { students[i].m_prices.push_back(price); } // 计算费用总和 int total = 0; for (int j = 0; j &lt; students[i].m_prices.size(); j++) { total += students[i].m_prices[j]; } students[i].m_total = total; } sort(students.begin(),students.end(),compare); for (int j = 0; j &lt; students.size(); j++) { // 输出排名 cout &lt;&lt; j+1 &lt;&lt; &quot; &quot;; // 输出姓名 cout &lt;&lt; students[j].m_name &lt;&lt; &quot; &quot;; // 输出总费用 cout &lt;&lt; students[j].m_total &lt;&lt; endl; } }
1.5.6测试数据或截图 image.png
1.5.7心得体会 通过编写学车费用统计排序程序，我掌握了多条件自定义排序的设计方法。学会了使用stringstream处理混合数据类型的输入，理解了类设计在组织复杂数据时的优势。最重要的是，意识到程序不仅要实现功能，还要考虑数据的完整性和排序的精确性。
1.6求n个整数的平均值与中位数 1.6.1题目内容 从键盘接收一个整数n，假定用户输入的n一定是满足3 &lt;= n &lt;= 100。接下来，从键盘接收n个整数存入数组。用户输入的整数，大小是杂乱无序的。 计算这n个数的平均值和中位数。中位数就是数组元素升序排列后，最中间的一个数(奇数个元素)，或中间两个元素平均值(偶数个元素)。
1.6.2题目要求 【输入格式】 第一个整数4告诉计算机要输入4个数字。第二行输入这四个数字，数字之间用空格分开。 4 3 1 2 9 【输出格式】 平均值保留2位小数，中位数保留1位小数。两项信息之间用纯英文逗号隔开，整个输出信息中不含空格。 mean=3.75, median=2.5
1.6.3设计思想 deepseek_mermaid_20260108_a9e34f.png
deepseek_mermaid_20260108_43a706.png
1.6.4算法分析 需要存储n个整数的数组：O(n) 其他变量占用常数空间：O(1)
1.6.5核心代码
// 求n个整数的平均值与中位数 #include #include #include #include #include using namespace std;
int main() { int n; cin &raquo; n; vector nums(n); int total = 0; for (int i = 0; i &lt; n; i++) { cin &raquo; nums[i]; total += nums[i]; } sort(nums.begin(),nums.end()); int len = nums.size(); // 求中位数 int mid_num = 0; if (len % 2 == 1) { mid_num = nums[len/2]; } else { mid_num = nums[len/2] + nums[(len/2)-1]; }
double avg = (double)total / (double)n; cout &lt;&lt; &quot;mean=&quot; &lt;&lt; avg &lt;&lt; &quot;median=&quot; &lt;&lt; mid_num &lt;&lt; endl; }
1.6.6测试数据或截图 image.png
1.6.7心得体会 通过编写这个求平均值和中位数的程序，我掌握了数据统计的基本方法。排序函数的使用让我明白了预处理数据的重要性，同时也注意到整数除法和浮点数除法的区别。程序虽然简单，但让我对数组操作和条件判断有了更深的理解。
1.7天才婴儿 1.7.1题目内容 育婴室里有从1到n编号的n个婴儿。有一天，有一个科研团队来到育婴室，科研团队认为某个婴儿的编号的值减去这个编号每一位数字的和代表一个婴儿的智商，他们同时有个智商衡量标准k，若某个婴儿的智商不小于k，那么科研团队就认为这个婴儿是天才。例如，编号为12的婴儿，他的智商应为12−(1+2)，即为9。科研团队想请你求出育婴室里有多少天才婴儿。
1.7.2题目要求 【输入格式】 输入包含两个整数n,k，分别表示婴儿的个数和科研团队的智商衡量标准。 【输出格式】 输出一个整数，表示育婴室里天才婴儿的数量。 【输入样例】 23 8 【输出格式】 14 【评测数据规模】 对于所有评测数据，1≤n，k≤10(9)。
1.7.3设计思想 deepseek_mermaid_20260108_39a1da.png
1.7.4算法分析 空间复杂度：O(1)（常数空间） 时间复杂度：O(n log n) 或更精确地说 O(n × d)，其中 d 是 n 的位数
1.7.5核心代码
// 天才婴儿 #include #include #include #include #include using namespace std;
int main() { int n,k; cin &raquo; n &raquo; k; int cnt = 0; for (int i = 1; i &lt;= n; i++) { int num = i; int temp = 0; while(num &gt; 0) { temp += num%10; num /= 10; } int k0 = i - temp; if (k0 &gt; k) { cnt++; } } cout &laquo; cnt; }
1.7.6测试数据或截图 image.png
1.7.7心得体会 通过这个数字特性统计程序，我掌握了数字分离求和的技巧。在遍历1到n的过程中，不仅学会了用取余和整除逐位提取数字，也加深了对条件判断的理解。虽然题目简单，但让我意识到细心处理边界情况的重要性。
1.8金币支付 1.8.1题目内容 小凯手中有两种面值的金币，两种面值均为正整数且彼此互素。每种金币小凯都有无数个。在不找零的情况下，仅凭这两种金币，有些物品他是无法准确支付的。现在小凯想知道在无法准确支付的物品中，最贵的价值是多少金币？注意：输入数据保证存在小凯无法准确支付的商品。输入数据仅一行，包含两个正整数a和b，它们之间用一个空格隔开，表示小凯手中金币的面值。其中，1≤a，b≤109
1.8.2题目要求 【输入格式】 输出仅一行，一个正整数N，表示不找零的情况下，小凯用手中的金币不能准确支付的最贵的物品的价值。 【输入样例】 3 7 【输出样例】 11
1.8.3设计思想 deepseek_mermaid_20260108_e5415c.png
1.8.5核心代码
// 金币支付 -&gt; 用a和b的线性组合不能被表示的最大整数 // 由于a和b互质, // 任何大于等于(a-1)(b-1)的整数都可以表示为a和b的非负整数线性组合 // 而ab - a - b正好等于(a-1)*(b-1) - 1,无法被表示,且是最大的这样的数 // 两个互质数，不能凑出的最大数 = 两数乘积减去两数之和 #include #include #include #include #include using namespace std;
int main() { int a,b; cin &raquo; a &raquo; b;
cout &lt;&lt; a*b - a - b; }
1.8.6测试数据或截图 image.png
1.8.7心得体会 通过这道题，我深刻体会到数学思维在编程中的重要性。看似复杂的线性组合问题，运用互质数的性质只需一个简洁公式就能解决，这让我认识到算法优化往往源于对问题本质的深入理解。
1.9鱼 1.9.1题目内容 在平面坐标系上给定 n 个不同的整点（也即横坐标与纵坐标皆为整数的点）。我们称从这 n 个点中选择 6 个不同的点所组成的有序六元组 &lt;A,B,C,D,E,F&gt; 是一条「鱼」，当且仅当：AB=AC,BD=CD,DE=DF（身形要对称），并且 ∠BAD,∠BDA 与 ∠CAD,∠CDA 都是锐角（脑袋和屁股显然不能是凹的），∠ADE,∠ADF 大于 90°（也即为钝角或平角，为了使尾巴不至于翘那么别扭）。 image.png
其中点的组成相同，但顺序不同的鱼视为不同的鱼，即 &lt;A,B,C,D,E,F&gt; 和 &lt;A,C,B,D,E,F&gt; 视为不同的两条鱼（毕竟鱼也有背和肚子的两面），同理 &lt;A,B,C,D,E,F&gt; 和 &lt;A,B,C,D,F,E&gt; 也可以视为不同的两条鱼（假设鱼尾巴可以打结）。 问给定的 n 个点可以构成多少条鱼。注意：数据保证 n 个点互不重复。
1.9.2题目要求 【输入格式】 第一行一个正整数 n ，代表平面上点的个数。 接下来 n 行每行两个整数 x,y ，代表点的横纵坐标。 【输出格式】 输出一行一个非负整数，代表鱼的个数。 【输入样例】 8 -2 0 -1 0 0 1 0 -1 1 0 2 0 3 1 3 -1 【输出样例】 16
1.9.3设计思想 deepseek_mermaid_20260108_2376e4.png
1.9.4算法分析 最坏时间复杂度：O(n⁶) 最坏空间复杂度：O(n⁶)（结果存储）
1.9.5核心代码 // 鱼 #include #include #include #include #include #include &lt;unordered_map&gt; using namespace std;
class Point { public: Point() {} Point(int x,int y) : m_x(x),m_y(y){} int m_x,m_y; };
// 计算两个向量的平方距离 int get_distance_sqrt(Point a, Point b) { int abx = b.m_x - a.m_x; int aby = b.m_y - a.m_y; return abxabx + abyaby; }
int dotProduct(Point A, Point B, Point C) { // 计算向量BA与向量BC的点积 int BAx = A.m_x - B.m_x; int BAy = A.m_x - B.m_x; int BCx = C.m_x - B.m_x; int BCy = C.m_x - B.m_x; return BAx * BCx + BAy * BCy; }
int main() { int n; cin &raquo; n; vector Points(n); for (int i = 0; i &lt; n; i++) { int x,y; cin &raquo; x &raquo; y; Points[i] = Point(x,y); }
vector&lt;unordered_map&lt;char,Point&gt;&gt; result; // 暴力查找每一个可以构成鱼的六元组 for (int a = 0; a &lt; n; a++) { for (int b = 0; b &lt; n; b++) { if (b == a) { continue; } for (int c = 0; c &lt; n; c++) { if (c == a || c == b) { continue; } if (get_distance_sqrt(Points[a],Points[b]) != get_distance_sqrt(Points[a],Points[c])) { continue; } for (int d = 0; d &lt; n; d++) { if (d == a || d == b || d == c){ continue; } if (get_distance_sqrt(Points[b],Points[d]) != get_distance_sqrt(Points[c],Points[d])) { continue; } for (int e = 0; e &lt; n; e++) { if (e == a || e == b || e == c || e == d) { continue; } for (int f = 0; f &lt; n; f++) { if (f == a || f == b || f == c || f == d || f == e) { continue; } if (get_distance_sqrt(Points[d],Points[e]) != get_distance_sqrt(Points[d],Points[f])) { continue; } // 角BAD,角BDA,角CAD,角CDA都是锐角 // 角ADE,角ADF大于90度 if (dotProduct(Points[b],Points[a],Points[d]) &gt; 0 &amp;&amp; dotProduct(Points[b],Points[d],Points[a]) &gt; 0 &amp;&amp; dotProduct(Points[c],Points[a],Points[d]) &gt; 0 &amp;&amp; dotProduct(Points[c],Points[d],Points[a]) &gt; 0 &amp;&amp; dotProduct(Points[a],Points[d],Points[e]) &lt; 0 &amp;&amp; dotProduct(Points[a],Points[d],Points[f]) &lt; 0 ) { // 维护可以构成鱼的六元组 unordered_map&lt;char,Point&gt; umap; umap.insert(make_pair('A',Points[a])); umap.insert(make_pair('B',Points[b])); umap.insert(make_pair('C',Points[c])); umap.insert(make_pair('D',Points[d])); umap.insert(make_pair('E',Points[e])); umap.insert(make_pair('F',Points[f])); result.push_back(umap); } } } } } } } cout &lt;&lt; result.size(); }
