// 迷你搜索引擎 #include #include #include #include #include &lt;unordered_map&gt; #include &lt;unordered_set&gt; #include #include using namespace std;
class File{ public: string title; vector text;
File() {} // 逐行添加文件内容 void addLine(const string&amp; line) { text.push_back(line); } // 返回文件总行数 int getLineCount() const { return text.size(); } // 获取指定行的内容 string getLine(int lineNum) const { if (lineNum &gt;= 0 &amp;&amp; lineNum &lt; text.size()) { return text[lineNum]; } return &quot;&quot;; } };
// 将大写转换为小写 string toLower(const string&amp; s) { string result = s; transform(result.begin(),result.end(),result.begin(),::tolower); return result; }
// 分割一行文本为单词 vector splitLine(const string&amp; line) { vector words; stringstream ss(toLower(line)); string word; while(ss &raquo; word) { words.push_back(word); } return words; }
int main() { // 读取N个文件文件 int N; cin &raquo; N; cin.ignore(); // 忽略换行符
vector&lt;File&gt; Files(N); // 建立倒排索引 // 索引结果: 单词 -&gt; 文件索引集合 unordered_map&lt;string, unordered_map&lt;int, unordered_set&lt;int&gt;&gt;&gt; invertedIndex; // 读取每个文件 for (int fileIdx = 0; fileIdx &lt; N; fileIdx++) { // 读取文件标题 string name; getline(cin,name); Files[fileIdx].title = name; // 读取文件内容 int lineNum = 0; // 当前行号 while(true) { string line; getline(cin,line); if (line == &quot;#&quot;) { break; } // 逐行存储文件内容 Files[fileIdx].addLine(line); // 处理当前行的单词,建立索引 vector&lt;string&gt; words = splitLine(line); // 去重: 同一行的同一个单词只记录一次 unordered_set&lt;string&gt; uniqueWords(words.begin(), words.end()); // 更新倒排索引 for (const string&amp; word : uniqueWords) { invertedIndex[word][fileIdx].insert(lineNum); } lineNum++; } } // 读取M个查询 int M; cin &gt;&gt; M; cin.ignore(); // 忽略换行符 // 处理每个查询 for (int i = 0; i &lt; M; i++) { string query; getline(cin, query); // 分割查询词 vector&lt;string&gt; queryWords = splitLine(query); if (queryWords.empty()) { cout &lt;&lt; &quot;0\nNot Found\n&quot;; continue; } // 1.找到包含所有查询词的文件 unordered_set&lt;int&gt; commonFiles; // 包含所有查询词的文件索引 // 初始化: 用第一个查询词的文件集合 if (invertedIndex.count(queryWords[0])) { for (const auto&amp; entry : invertedIndex[queryWords[0]]) { commonFiles.insert(entry.first); // entry.first是文件索引 } } // 取交集: 确保文件包含所有查询词 for (size_t i = 1; i &lt; queryWords.size(); i++) { const string&amp; word = queryWords[i]; if (!invertedIndex.count(word)) { // 如果某个词在任何文件中都不存在，交集为空 commonFiles.clear(); break; } unordered_set&lt;int&gt; currentFiles; for (const auto&amp; entry : invertedIndex[word]) { currentFiles.insert(entry.first); } // 取交集 unordered_set&lt;int&gt; newCommonFiles; for (int fileIdx : commonFiles) { if (currentFiles.count(fileIdx)) { newCommonFiles.insert(fileIdx); } } commonFiles = newCommonFiles; } // 2. 输出符合条件的文件数 cout &lt;&lt; commonFiles.size() &lt;&lt; endl; // 如果没有符合条件的文件则输出未找到 if (commonFiles.empty()) { cout &lt;&lt; &quot;Not Found\n&quot;; } else { // 如果有符合条件的文件: 按文件输入顺序输出（0到N-1） for (int fileIdx = 0; fileIdx &lt; N; fileIdx++) { if (commonFiles.count(fileIdx)) { // 输出文件标题 cout &lt;&lt; Files[fileIdx].title &lt;&lt; endl; //收集相关行号 unordered_set&lt;int&gt; relevantLines; for (const string&amp; word : queryWords) { if (invertedIndex.count(word) &amp;&amp; invertedIndex[word].count(fileIdx)) { const unordered_set&lt;int&gt;&amp; lines = invertedIndex[word][fileIdx]; relevantLines.insert(lines.begin(), lines.end()); } } // 将行号转换为向量并排序（按行号顺序输出） vector&lt;int&gt; sortedLines(relevantLines.begin(), relevantLines.end()); sort(sortedLines.begin(), sortedLines.end()); // 输出包含查询词的行 for (int lineNum : sortedLines) { cout &lt;&lt; Files[fileIdx].getLine(lineNum) &lt;&lt; endl; } } } } } }
