// 记忆化搜索 // 终止条件: 当num递归到1时,当num是质数时 // 递推表达式: f(n) = 1 sum(f(n / i)) // 整数因子分解问题 #include #include using namespace std;
map&lt;int,int&gt; memo; int solve(int num) { if (num == 1) return 1;
if (memo.find(num) != memo.end()) return memo[num]; int count = 1; for (int i = 2; i &lt;= num / 2; i++) { if (num % i == 0) { count += solve(num / i); } } memo[num] = count; return count; }
int main() { int n; while(cin &raquo; n) { cout &laquo; solve(n) &laquo; endl; } }
