2.3.5核心代码 // 动态规划 #include #include #include #include using namespace std;
int main() { int N,M; // N枚硬币总数,M付款金额 cin &raquo; N &raquo; M; vector coins(N); // 读取N之后再创建硬币 for (int i = 0; i &lt; N; i++) { cin &raquo; coins[i]; }
sort(coins.begin(),coins.end()); // 从小到大排序 // dp[i][j] 表示第i+1个物品在背包为j的空格下的最大价值 vector&lt;vector&lt;int&gt; &gt; dp(N,vector&lt;int&gt;(M + 1)); // 老编译器版本 int bagweight = M; // 路径记录 vector&lt;vector&lt;bool&gt; &gt; choice(N,vector&lt;bool&gt;(M + 1,false)); // 初始化 for (int i = 0; i &lt;= bagweight; i++) { if (i &gt;= coins[0]) { dp[0][i] = coins[0]; choice[0][i] = true; // 选择第一个硬币 } } // 动态规划方程 // 先遍历物品,再遍历背包重量 for (int i = 1; i &lt; N; i++) { for (int j = 0; j &lt;= bagweight; j++) { // cout &lt;&lt; &quot;debug: &quot; &lt;&lt; dp[i][j] &lt;&lt; endl; if (j &gt;= coins[i] &amp;&amp; coins[i] + dp[i-1][j - coins[i]] &gt; dp[i-1][j]) { dp[i][j] = coins[i] + dp[i-1][j - coins[i]]; choice[i][j] = true; // 选择了第i个硬币 } else { // cout &lt;&lt; &quot;debug: 大小不够&quot; &lt;&lt; endl; dp[i][j] = dp[i-1][j]; } // cout &lt;&lt; dp[i][j] &lt;&lt; endl; } } // 判断是否能够凑出 // 当背包的最大价值刚好等于自己的最大容量的时候 // 说明此时刚好能够凑出 // cout &lt;&lt; dp[N-1][M] &lt;&lt; endl; if (dp[N-1][M] == M) { cout &lt;&lt; &quot;Yes&quot; &lt;&lt; endl; } else { cout &lt;&lt; &quot;No Solution&quot; &lt;&lt; endl; } // // debug // for (int i = 0; i &lt; N; i++) { // for (int j = 0; j &lt;= bagweight; j++) { // cout &lt;&lt; choice[i][j] &lt;&lt; &quot; &quot;; // } // cout &lt;&lt; endl; // } // 回溯构造序列 // 题目指的的最小序列指的是字典序 vector&lt;int&gt; result; int i = N - 1,j = M; while(i &gt;= 0 &amp;&amp; j &gt; 0) { if (choice[i][j]) { result.push_back(coins[i]); j -= coins[i]; } i--; } sort(result.begin(), result.end()); for (int k = 0; k &lt; result.size(); k++) { if (k != 0) cout &lt;&lt; &quot; &quot;; cout &lt;&lt; result[k]; } cout &lt;&lt; endl; }
