// 5.3 // 贪心算法 // 多处最优服务次序问题 #include #include #include #include #include using namespace std;
int main() { int n,s; // n个顾客 s处服务地点 cin &raquo; n &raquo; s; vector clinets(n); vector services(s); vector result(n); for (int i = 0; i &lt; n; i++) { cin &raquo; clinets[i]; }
