2.8.5核心代码
#include #include #include #include #include #include using namespace std;
// 回溯法与分支定界法 // n皇后问题
// 存储每个方案 vector&lt;vector&lt;vector &gt; &gt; result;
// 补充: 这里不需要遍历行,因为在单层搜索的过程中,每一层递归,只会选 // for循环里面的一个元素 // 满足n皇后就返回真,不满足n皇后就返回假 bool isValid(vector&lt;vector &gt; chessboard,int col, int row, int n) { // 遍历列 for (int i = 0; i &lt; row; i++) { if (chessboard[i][col] == &lsquo;&rsquo;) { return false; } } // 遍历45度 for (int i = row - 1,j = col - 1; i &gt;= 0 &amp;&amp; j &gt;= 0; i&ndash;,j&ndash;) { if (chessboard[i][j] == &lsquo;&rsquo;) { return false; } }
// 遍历135度 for (int i = row - 1, j = col + 1; i &gt;= 0 &amp;&amp; j &lt; n; i--,j++) { if (chessboard[i][j] == '*') { return false; } } return true; }
// 回溯法暴搜索n皇后问题 void backtracking(int n,int row,vector&lt;vector &gt;&amp; chessboard) { if (row == n) { result.push_back(chessboard); return; }
for (int col = 0; col &lt; n; col++) { if (isValid(chessboard,col,row,n)) { // 如果同行同列同斜线存在就不继续搜索了 chessboard[row][col] = '*'; // 放入皇后 backtracking(n,row + 1,chessboard); // 继续递归 chessboard[row][col] = '.'; // 回溯 } } }
int main() { // &lsquo;&lsquo;表示放置皇后 &lsquo;.&lsquo;表示不防止皇后 int n; // nn的棋盘 cin &raquo; n; // 构造棋盘 vector&lt;vector &gt; chessboard(n,vector(n)); for (int i = 0; i &lt; n; i++) { for (int j = 0; j &lt; n; j++) { chessboard[i][j] = &lsquo;.&rsquo;; } }
// 存储方案总数 vector&lt;vector&lt;int&gt; &gt; count; // 暴搜计算结果 backtracking(n,0,chessboard); // 先从第0行开始搜索 for (int i = 0; i &lt; result.size(); i++) { vector&lt;int&gt; temp; for (int j = 0; j &lt; n; j++) { for (int k = 0; k &lt; n; k++) { if (result[i][j][k] == '*') { // 如果第i个结果的第j行第k列示皇后则统计数据 temp.push_back(k); } } } count.push_back(temp); } // 打印数据 for (int i = 0; i &lt; count.size(); i++) { for (int j = 0; j &lt; count[0].size() - 1; j++) { cout &lt;&lt; count[i][j] &lt;&lt; &quot; &quot;; } cout &lt;&lt; count[i][count[0].size()-1] &lt;&lt; endl; } // 题目理解错误的代码 // // 统计结果 // for (int i = 0; i &lt; result.size(); i++) { // for (int j = 0; j &lt; n; j++) { // for (int k = 0; k &lt; n; k++) { // if (result[i][j][k] == '*') { // 如果第i个结果的第j行第k列示皇后则统计数据 // cnt[j][k]++; // } // } // } // } // // 输出结果: 输出的是所有可能的放置情况,每一行代表一种方案 // // 该行的数字表示每一行的皇后所在的列号 // for (int i = 0; i &lt; cnt.size(); i++) { // for (int j = 0; j &lt; cnt[0].size() - 1; j++) { // cout &lt;&lt; cnt[i][j] &lt;&lt; &quot; &quot;; // } // cout &lt;&lt; cnt[i][cnt[0].size() - 1] &lt;&lt; endl; // } cout &lt;&lt; &quot;Total=&quot; &lt;&lt; result.size() &lt;&lt; endl; }
