3.1.5核心代码 第一题#include #include using namespace std;
struct Node { bool flag; int x, y; };
Node map[20][20]; vector road; int N, X[20], Y[20], sum; int dir[4][2] = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};
bool dfs(int x, int y) { if (x == N - 1 &amp;&amp; y == N - 1) { for (int i = 0; i &lt; N; i++) { if (X[i] || Y[i] || sum) return false; road.push_back(x * N + y); return true; } }
road.push_back(x * N + y); map[x][y].flag = true; for (int i = 0; i &lt; 4; i++) { int tx = x + dir[i][0]; int ty = y + dir[i][1]; if (tx &lt; 0 || tx &gt; (N - 1) || ty &lt; 0 || ty &gt; (N - 1)) continue; if (!map[tx][ty].flag &amp;&amp; (X[tx] &gt; 0 &amp;&amp; Y[ty] &gt; 0)) { X[tx]--;Y[ty]--;sum -= 2; if (dfs(tx, ty)) return true; else { X[tx]++; Y[ty]++; sum += 2; } } } map[x][y].flag = false; road.erase(road.begin() + road.size() - 1); return false; }
int main() { cin &raquo; N; for (int i = 0; i &lt; N; i++){ cin &raquo; Y[i]; sum += Y[i]; } for (int i = 0; i &lt; N; i++) { cin &raquo; X[i]; sum += X[i]; } for (int i = 0; i &lt; N; i++) { for (int j = 0; j &lt; N; j++) { map[i][j].flag = false; map[i][j].x = i; map[i][j].y = j; } } X[0]&ndash;;Y[0]&ndash;;sum -= 2; dfs(0, 0); for (int i = 0; i &lt; road.size(); i++) cout &laquo; road[i] &laquo; &rsquo; &lsquo;; return 0; } 3.1.6测试数据或截图 image.png
