3.6.5核心代码 #include #include #include using namespace std; const int N = 1e5 + 5; int a[N]; //储存初始顺序的数组 bool st[N]; //标记数组 int main() { int n; cin &raquo; n; //输入数组 for (int i = 1; i &lt;= n; i++) { cin &raquo; a[i]; }
int cnt = 0; //记录初始环数 for (int i = 1; i &lt;= n; i++) { if (!st[i]) { //没有被标记，找到一个环的起点 cnt++; for (int j = i; !st[j]; j = a[j]) { //访问这个环，将这个环中所有结点都进行标记 st[j] = true; } } } cout &lt;&lt; n - cnt; } 3.6.6测试数据或截图 image.png
