int main() { const int TOTAL_PEOPLE = 50; const int SPECIAL_GROUP_SIZE = 7;
// 假设编号0-6是那7个人 vector&lt;int&gt; is_special(TOTAL_PEOPLE, 0); for (int i = 0; i &lt; SPECIAL_GROUP_SIZE; i++) { is_special[i] = 1; } int handshakes = 0; // 遍历所有可能的握手对 for (int i = 0; i &lt; TOTAL_PEOPLE; i++) { for (int j = i + 1; j &lt; TOTAL_PEOPLE; j++) { // 如果两个人都属于特殊组，则不握手 if (is_special[i] &amp;&amp; is_special[j]) { continue; } handshakes++; } } cout &lt;&lt; handshakes &lt;&lt; endl; return 0; } 3.7.6测试数据或截图 时间复杂度: O(n²)，其中n=50（固定规模，实际为常数操作） 空间复杂度: O(n)，使用了一个大小为n的标记数组
