// Long-term locks for processes struct sleeplock { uint locked; // Is the lock held? struct spinlock lk; // spinlock protecting this sleep lock
// For debugging: char *name; // Name of lock. int pid; // Process holding lock };
// Sleeping locks
#include &ldquo;types.h&rdquo; #include &ldquo;riscv.h&rdquo; #include &ldquo;defs.h&rdquo; #include &ldquo;param.h&rdquo; #include &ldquo;memlayout.h&rdquo; #include &ldquo;spinlock.h&rdquo; #include &ldquo;proc.h&rdquo; #include &ldquo;sleeplock.h&rdquo;
void initsleeplock(struct sleeplock *lk, char *name) { initlock(&amp;lk-&gt;lk, &ldquo;sleep lock&rdquo;); lk-&gt;name = name; lk-&gt;locked = 0; lk-&gt;pid = 0; }
void acquiresleep(struct sleeplock *lk) { acquire(&amp;lk-&gt;lk); while (lk-&gt;locked) { sleep(lk, &amp;lk-&gt;lk); } lk-&gt;locked = 1; lk-&gt;pid = myproc()-&gt;pid; release(&amp;lk-&gt;lk); }
void releasesleep(struct sleeplock *lk) { acquire(&amp;lk-&gt;lk); lk-&gt;locked = 0; lk-&gt;pid = 0; wakeup(lk); release(&amp;lk-&gt;lk); }
int holdingsleep(struct sleeplock *lk) { int r;
acquire(&amp;lk-&gt;lk); r = lk-&gt;locked &amp;&amp; (lk-&gt;pid == myproc()-&gt;pid); release(&amp;lk-&gt;lk); return r; }
自旋锁spinlock.c/spinlock.h // Mutual exclusion lock. struct spinlock { uint locked; // Is the lock held?
// For debugging: char *name; // Name of lock. struct cpu *cpu; // The cpu holding the lock. };
// Mutual exclusion spin locks.
#include &ldquo;types.h&rdquo; #include &ldquo;param.h&rdquo; #include &ldquo;memlayout.h&rdquo; #include &ldquo;spinlock.h&rdquo; #include &ldquo;riscv.h&rdquo; #include &ldquo;proc.h&rdquo; #include &ldquo;defs.h&rdquo;
void initlock(struct spinlock *lk, char *name) { lk-&gt;name = name; lk-&gt;locked = 0; lk-&gt;cpu = 0; }
// Acquire the lock. // Loops (spins) until the lock is acquired. void acquire(struct spinlock *lk) { push_off(); // disable interrupts to avoid deadlock. if(holding(lk)) panic(&ldquo;acquire&rdquo;);
// On RISC-V, sync_lock_test_and_set turns into an atomic swap: // a5 = 1 // s1 = &amp;lk-&gt;locked // amoswap.w.aq a5, a5, (s1) while(__sync_lock_test_and_set(&amp;lk-&gt;locked, 1) != 0) ;
// Tell the C compiler and the processor to not move loads or stores // past this point, to ensure that the critical section&rsquo;s memory // references happen strictly after the lock is acquired. // On RISC-V, this emits a fence instruction. __sync_synchronize();
// Record info about lock acquisition for holding() and debugging. lk-&gt;cpu = mycpu(); }
// Release the lock. void release(struct spinlock *lk) { if(!holding(lk)) panic(&ldquo;release&rdquo;);
lk-&gt;cpu = 0;
// Tell the C compiler and the CPU to not move loads or stores // past this point, to ensure that all the stores in the critical // section are visible to other CPUs before the lock is released, // and that loads in the critical section occur strictly before // the lock is released. // On RISC-V, this emits a fence instruction. __sync_synchronize();
// Release the lock, equivalent to lk-&gt;locked = 0. // This code doesn&rsquo;t use a C assignment, since the C standard // implies that an assignment might be implemented with // multiple store instructions. // On RISC-V, sync_lock_release turns into an atomic swap: // s1 = &amp;lk-&gt;locked // amoswap.w zero, zero, (s1) __sync_lock_release(&amp;lk-&gt;locked);
pop_off(); }
// Check whether this cpu is holding the lock. // Interrupts must be off. int holding(struct spinlock *lk) { int r; r = (lk-&gt;locked &amp;&amp; lk-&gt;cpu == mycpu()); return r; }
// push_off/pop_off are like intr_off()/intr_on() except that they are matched: // it takes two pop_off()s to undo two push_off()s. Also, if interrupts // are initially off, then push_off, pop_off leaves them off.
void push_off(void) { int old = intr_get();
// disable interrupts to prevent an involuntary context // switch while using mycpu(). intr_off();
if(mycpu()-&gt;noff == 0) mycpu()-&gt;intena = old; mycpu()-&gt;noff += 1; }
void pop_off(void) { struct cpu *c = mycpu(); if(intr_get()) panic(&ldquo;pop_off - interruptible&rdquo;); if(c-&gt;noff &lt; 1) panic(&ldquo;pop_off&rdquo;); c-&gt;noff -= 1; if(c-&gt;noff == 0 &amp;&amp; c-&gt;intena) intr_on(); }
